"use client";
import { useRef } from "react";
import {
  TypeGlyphs,
  typeUnits,
  typeInteractive,
  useTypeMotion,
  type TypographyMotionProps,
} from "./typography-shared";
import { typeEaseOut, typeStaggerProgress } from "./typography-math";
export interface CinematicTextProps extends TypographyMotionProps {
  distance?: number;
  stagger?: number;
  split?: "lines" | "words" | "chars";
  direction?: "alternating" | "left" | "right";
}
export function CinematicText({
  text = "Every\nSingle\nMile\nCounts.",
  distance = 180,
  stagger = 0.65,
  split = "lines",
  direction = "alternating",
  ...props
}: CinematicTextProps) {
  const root = useRef<HTMLDivElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const units = typeUnits(root.current!);
      units.forEach((unit, i) => {
        const q = typeEaseOut(typeStaggerProgress(p, i, units.length, stagger));
        const sign = direction === "left" ? -1 : direction === "right" ? 1 : i % 2 ? -1 : 1;
        unit.style.transform = `translateX(${sign * distance * (1 - q)}px)`;
        unit.style.opacity = String(q);
      });
    },
    `${text}:${distance}:${stagger}:${split}:${direction}`,
  );
  return (
    <div
      ref={root}
      className={props.className}
      style={{ overflow: "clip", ...props.style }}
      aria-label={text}
      data-typography="cinematic-text"
      {...typeInteractive(props.trigger)}
    >
      <div aria-hidden="true">
        <TypeGlyphs text={text} split={split} />
      </div>
    </div>
  );
}
